package com.fooddelivery.order; import org.springframework.stereotype.Service; import org.springframework.web.reactive.function.client.WebClient; import java.math.BigDecimal; @Service public class RestaurantClient{final WebClient.Builder builder; RestaurantClient(WebClient.Builder b){builder=b;} record MenuItem(Long id,String name,String description,BigDecimal price,String imageUrl,boolean available,Long restaurantId){} public MenuItem getItem(Long id){return builder.baseUrl("http://RESTAURANT-SERVICE").build().get().uri("/api/menu-items/{id}",id).retrieve().bodyToMono(MenuItem.class).block();}}